test('invoiceTotals returns subtotal and total for a single line', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
