        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
      },
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 10,
        unitPrice: 9500,
        vatRate: 21,
      },
      {
        sku: 'STICKER',
        name: 'Sticker sheet',
        qty: 100,
        unitPrice: 50,
        vatRate: 21,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 17000 + 95000 + 5000);
  assert.equal(totals.total, 117000);
